css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; inset: 12%; border-radius: 50%; border: 1px dashed color-mix(in srgb, var(--accent-2) 28%, transparent); }
.loader span { position: absolute; inset: 0; margin: auto; width: 0; height: 0; animation: comet calc(var(--loader-speed) * 1.4) linear infinite; }
.loader span::before { content: ''; position: absolute; left: calc(var(--loader-size) * .38); top: 50%; width: calc(var(--loader-size) * .13); height: calc(var(--loader-size) * .13); margin-top: calc(var(--loader-size) * -.065); border-radius: 50%; background: radial-gradient(circle at 35% 35%, #fff, var(--accent)); box-shadow: 0 0 calc(var(--loader-size) * .1) var(--accent), calc(var(--loader-size) * -.11) 0 calc(var(--loader-size) * .09) color-mix(in srgb, var(--accent) 55%, transparent), calc(var(--loader-size) * -.22) 0 calc(var(--loader-size) * .12) color-mix(in srgb, var(--accent) 28%, transparent); }
@keyframes comet { to { transform: rotate(360deg); } }
